FALLBACKS = {
    "add": "Images/32x32/Famille_ajouter.png",
    "edit": "Images/32x32/Famille_modifier.png",
    "delete": "Images/32x32/Famille_supprimer.png",
    "calendar": "Images/32x32/Calendrier.png",
    "people": "Images/32x32/Personnes.png",
    "settings": "Images/32x32/Configuration2.png",
}


def _couleur_hex(role):
    try:
        from Utils import UTILS_Interface
        couleur = UTILS_Interface.GetCouleurRole(role)
        return "#%02X%02X%02X" % (couleur.Red(), couleur.Green(), couleur.Blue())
    except Exception:
        return "#212121"


def _bitmap_fallback(nom, taille):
    try:
        import wx
        import Chemins
        chemin = Chemins.GetStaticIconPath(FALLBACKS[nom], taille=taille)
        bitmap = wx.Bitmap(chemin, wx.BITMAP_TYPE_ANY)
        if bitmap.IsOk() and (bitmap.GetWidth() != taille or bitmap.GetHeight() != taille):
            image = bitmap.ConvertToImage().Scale(taille, taille, wx.IMAGE_QUALITY_HIGH)
            bitmap = wx.Bitmap(image)
        return bitmap
    except Exception:
        try:
            return wx.NullBitmap
        except Exception:
            return None


def GetBitmap(nom, taille=24, role="on_surface"):
    """Retourne un ``wx.Bitmap`` Fluent recoloré selon le thème courant."""
    try:
        taille = max(12, min(64, int(taille)))
    except Exception:
        taille = 24
    if nom not in SVG:
        return _bitmap_fallback(nom, taille) if nom in FALLBACKS else None

    couleur = _couleur_hex(role)
    cle = (nom, taille, couleur)
    if cle in _CACHE:
        return _CACHE[cle]

    try:
        import wx.svg
        data = SVG[nom].replace("#212121", couleur).encode("utf-8")
        image = wx.svg.SVGimage.CreateFromBytes(data)
        try:
            bitmap = image.ConvertToBitmap(width=taille, height=taille)
        except TypeError:
            bitmap = image.ConvertToBitmap(scale=float(taille) / 24.0)
        if bitmap is not None and bitmap.IsOk():
            _CACHE[cle] = bitmap
            return bitmap
    except Exception:
        pass

    bitmap = _bitmap_fallback(nom, taille)
    if bitmap is not None:
        _CACHE[cle] = bitmap
    return bitmap


def ViderCache():
    """À appeler après changement de thème/accent si nécessaire."""
    _CACHE.clear()
